import{_ as e,o,c as t,a2 as l}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_01_package_boundary.png",c="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_02_lifecycle_state.png",n="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_03_path_mapgrid.png",r="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_04_velocity_rollout.png",s="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_05_critics_scoring.png",d="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_06_results_outputs.png",f=JSON.parse('{"title":"每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流","description":"DWB 每个控制周期生成一批速度，推演未来约 1.7 s 的轨迹，再让多个 Critic 评分。违法轨迹淘汰，合法轨迹中总分最低者成为本周期控制指令。","frontmatter":{"title":"每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流","description":"DWB 每个控制周期生成一批速度，推演未来约 1.7 s 的轨迹，再让多个 Critic 评分。违法轨迹淘汰，合法轨迹中总分最低者成为本周期控制指令。","date":"2026-07-21","section":"三 · 局部控制与速度生成","readingTime":6,"source":"2026-07-21/nav2_dwb_controller_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-21/nav2_dwb_01_package_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-dwb-controller-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流"}],["meta",{"property":"og:description","content":"DWB 每个控制周期生成一批速度，推演未来约 1.7 s 的轨迹，再让多个 Critic 评分。违法轨迹淘汰，合法轨迹中总分最低者成为本周期控制指令。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-dwb-controller-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_01_package_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-21"}],["meta",{"name":"twitter:title","content":"每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流"}],["meta",{"name":"twitter:description","content":"DWB 每个控制周期生成一批速度，推演未来约 1.7 s 的轨迹，再让多个 Critic 评分。违法轨迹淘汰，合法轨迹中总分最低者成为本周期控制指令。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_dwb_01_package_boundary.png"}]],"prev":{"text":"一条路径如何变成速度？拆解 `nav2_controller` 的插件矩阵与闭环数据流","link":"/nav2/nav2-controller-full-dataflow"},"next":{"text":"一次采样 1000 条轨迹，机器人最后听谁的？拆解 Nav2 MPPI 全调用、状态与数据流","link":"/nav2/nav2-mppi-controller-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-dwb-controller-full-dataflow.md","filePath":"nav2/nav2-dwb-controller-full-dataflow.md","lastUpdated":null}'),p={name:"nav2/nav2-dwb-controller-full-dataflow.md"};function h(_,a,u,b,m,v){return o(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="每-50-毫秒-试跑-420-条未来-机器人为什么只执行这一条-拆解-nav2-dwb-全调用、状态与数据流" tabindex="-1">每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流 <a class="header-anchor" href="#每-50-毫秒-试跑-420-条未来-机器人为什么只执行这一条-拆解-nav2-dwb-全调用、状态与数据流" aria-label="Permalink to &quot;每 50 毫秒“试跑”420 条未来，机器人为什么只执行这一条？拆解 Nav2 DWB 全调用、状态与数据流&quot;">​</a></h1><p>DWB 每个控制周期生成一批速度，推演未来约 <code>1.7 s</code> 的轨迹，再让多个 Critic 评分。违法轨迹淘汰，合法轨迹中总分最低者成为本周期控制指令。</p><h2 id="一、dwb-到底负责什么" tabindex="-1">一、DWB 到底负责什么 <a class="header-anchor" href="#一、dwb-到底负责什么" aria-label="Permalink to &quot;一、DWB 到底负责什么&quot;">​</a></h2><h3 id="_1-1-它是-controller-插件" tabindex="-1">1.1 它是 Controller 插件 <a class="header-anchor" href="#_1-1-它是-controller-插件" aria-label="Permalink to &quot;1.1 它是 Controller 插件&quot;">​</a></h3><p><code>DWBLocalPlanner</code> 实现 <code>nav2_core::Controller</code>，由 <code>controller_server</code> 动态加载，不是独立节点。它接收全局路径、机器人位姿、里程计速度和局部 Costmap，返回 <code>TwistStamped</code>。</p><p>Action 管理、进度检查、到达判定以及最终速度 Topic 发布都属于 Controller Server。DWB 只负责局部速度搜索。</p><h3 id="_1-2-八个包组成一条算法链" tabindex="-1">1.2 八个包组成一条算法链 <a class="header-anchor" href="#_1-2-八个包组成一条算法链" aria-label="Permalink to &quot;1.2 八个包组成一条算法链&quot;">​</a></h3><ul><li><code>dwb_core</code>：主循环、轨迹生成与评分协议。</li><li><code>dwb_plugins</code>：两类轨迹生成器。</li><li><code>dwb_critics</code>：路径、目标、障碍物等评分器。</li><li><code>costmap_queue</code>：栅格距离传播队列。</li><li><code>dwb_msgs</code>、<code>nav_2d_msgs</code>：轨迹、速度与评估消息。</li><li><code>nav_2d_utils</code>：Path、Pose、Twist 的二维转换工具。</li><li><code>nav2_dwb_controller</code>：聚合包与插件导出入口。</li></ul><p><img src="'+i+'" alt="DWB 包边界与外部接口"></p><h2 id="二、调用与状态如何流动" tabindex="-1">二、调用与状态如何流动 <a class="header-anchor" href="#二、调用与状态如何流动" aria-label="Permalink to &quot;二、调用与状态如何流动&quot;">​</a></h2><h3 id="_2-1-lifecycle-建立运行环境" tabindex="-1">2.1 Lifecycle 建立运行环境 <a class="header-anchor" href="#_2-1-lifecycle-建立运行环境" aria-label="Permalink to &quot;2.1 Lifecycle 建立运行环境&quot;">​</a></h3><p><code>configure()</code> 读取运动学参数，加载 TrajectoryGenerator、Critic 和调试发布器。<code>activate()</code>、<code>deactivate()</code> 控制 Publisher，<code>cleanup()</code> 释放资源。</p><p><code>setPlan()</code> 将 <code>nav_msgs/Path</code> 转成 <code>global_plan_</code>，同时重置生成器和 Critic。速度上限通过 <code>setSpeedLimit()</code> 注入。</p><h3 id="_2-2-状态跨周期保留" tabindex="-1">2.2 状态跨周期保留 <a class="header-anchor" href="#_2-2-状态跨周期保留" aria-label="Permalink to &quot;2.2 状态跨周期保留&quot;">​</a></h3><p>DWB 并非每个周期完全从零开始。以下状态会影响下一轮搜索：</p><ul><li>已裁剪的 <code>global_plan_</code>。</li><li><code>OscillationCritic</code> 记录的振荡方向限制。</li><li><code>RotateToGoalCritic</code> 的接近目标与旋转阶段状态。</li><li>当前速度上限、加速度和减速度约束。</li></ul><p><img src="'+c+'" alt="DWB Lifecycle 与跨周期状态"></p><h2 id="三、path-如何变成评分基准" tabindex="-1">三、Path 如何变成评分基准 <a class="header-anchor" href="#三、path-如何变成评分基准" aria-label="Permalink to &quot;三、Path 如何变成评分基准&quot;">​</a></h2><h3 id="_3-1-路径先裁剪再变换" tabindex="-1">3.1 路径先裁剪再变换 <a class="header-anchor" href="#_3-1-路径先裁剪再变换" aria-label="Permalink to &quot;3.1 路径先裁剪再变换&quot;">​</a></h3><p>每个周期，DWB 把机器人位姿变换到 Path 坐标系，在 <code>prune_distance</code> 内找到有效起点，截取局部 Costmap 可覆盖的前向路径，再变换到 Costmap 的 <code>global_frame</code>。已走过的前缀会被删除，最终目标位姿单独保留。</p><p>这一步决定 Critic 看到的不是整条全局路径，而是与当前位置和局部地图匹配的一段参考走廊。</p><h3 id="_3-2-mapgrid-把几何关系变成距离场" tabindex="-1">3.2 MapGrid 把几何关系变成距离场 <a class="header-anchor" href="#_3-2-mapgrid-把几何关系变成距离场" aria-label="Permalink to &quot;3.2 MapGrid 把几何关系变成距离场&quot;">​</a></h3><p><code>PathDist</code>、<code>GoalDist</code>、<code>PathAlign</code> 和 <code>GoalAlign</code> 会在 Costmap 栅格上建立距离场。路径或目标附近的栅格距离较小，向外通过队列传播，最终得到近似曼哈顿距离。</p><p>候选轨迹只需查询端点或前向点所在栅格的距离值，适合高频批量评分。</p><p><img src="'+n+'" alt="Path 裁剪、坐标变换与 MapGrid"></p><h2 id="四、约-420-条候选轨迹从哪里来" tabindex="-1">四、约 420 条候选轨迹从哪里来 <a class="header-anchor" href="#四、约-420-条候选轨迹从哪里来" aria-label="Permalink to &quot;四、约 420 条候选轨迹从哪里来&quot;">​</a></h2><h3 id="_4-1-速度采样窗口" tabindex="-1">4.1 速度采样窗口 <a class="header-anchor" href="#_4-1-速度采样窗口" aria-label="Permalink to &quot;4.1 速度采样窗口&quot;">​</a></h3><p>当前配置中，Controller Server 以 <code>20 Hz</code> 运行，也就是每 <code>50 ms</code> 计算一次控制。差速底盘对 <code>vx</code> 采样 <code>20</code> 份，<code>vy</code> 被限制为零，只剩 <code>1</code> 份；<code>vtheta</code> 采样 <code>20</code> 份，并可能补入零角速度。因此候选规模约为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>20 × 1 × 21 ≈ 420</span></span></code></pre></div><p>全零组合和不满足约束的速度会被过滤，实际数量可能略少。</p><h3 id="_4-2-两类生成器代表两种窗口" tabindex="-1">4.2 两类生成器代表两种窗口 <a class="header-anchor" href="#_4-2-两类生成器代表两种窗口" aria-label="Permalink to &quot;4.2 两类生成器代表两种窗口&quot;">​</a></h3><p><code>StandardTrajectoryGenerator</code> 用完整 <code>sim_time</code> 判断未来可达速度，并按加速度限制逐步积分位姿。它允许机器人在推演过程中继续加速或减速。</p><p><code>LimitedAccelGenerator</code> 使用一个控制周期 <code>sim_period</code> 形成经典 Dynamic Window，只在当前速度附近采样短时可达速度，随后用该候选速度推演整条轨迹。</p><p>两者评分接口相同，但速度窗口含义不同。</p><p><img src="'+r+'" alt="速度窗口与未来轨迹推演"></p><h2 id="五、critic-如何选出赢家" tabindex="-1">五、Critic 如何选出赢家 <a class="header-anchor" href="#五、critic-如何选出赢家" aria-label="Permalink to &quot;五、Critic 如何选出赢家&quot;">​</a></h2><h3 id="_5-1-评分协议" tabindex="-1">5.1 评分协议 <a class="header-anchor" href="#_5-1-评分协议" aria-label="Permalink to &quot;5.1 评分协议&quot;">​</a></h3><p>每周期各 Critic 的 <code>prepare()</code> 执行一次。每个候选速度生成 <code>Trajectory2D</code>，按配置顺序评分。</p><p>Critic 抛出非法轨迹异常时，候选立即淘汰。合法轨迹总分是各项原始分数乘权重后的和。累计分数高于当前最优值时可短路，最终最低分轨迹胜出。</p><h3 id="_5-2-十个-critic-的职责" tabindex="-1">5.2 十个 Critic 的职责 <a class="header-anchor" href="#_5-2-十个-critic-的职责" aria-label="Permalink to &quot;5.2 十个 Critic 的职责&quot;">​</a></h3><ul><li>导航方向：<code>PathDist</code>、<code>GoalDist</code>、<code>PathAlign</code>、<code>GoalAlign</code>。</li><li>碰撞安全：<code>BaseObstacle</code>、<code>ObstacleFootprint</code>。</li><li>动作约束：<code>RotateToGoal</code>、<code>Oscillation</code>、<code>PreferForward</code>、<code>Twirling</code>。</li></ul><p>当前配置启用了其中七个：<code>RotateToGoal</code>、<code>Oscillation</code>、<code>BaseObstacle</code>、<code>GoalAlign</code>、<code>PathAlign</code>、<code>PathDist</code> 和 <code>GoalDist</code>。</p><h3 id="_5-3-权重决定行为偏好" tabindex="-1">5.3 权重决定行为偏好 <a class="header-anchor" href="#_5-3-权重决定行为偏好" aria-label="Permalink to &quot;5.3 权重决定行为偏好&quot;">​</a></h3><p>现有参数中，<code>PathAlign</code> 与 <code>PathDist</code> 的 scale 为 <code>32</code>，<code>GoalAlign</code> 与 <code>GoalDist</code> 为 <code>24</code>，<code>RotateToGoal</code> 为 <code>32</code>，<code>BaseObstacle</code> 为 <code>0.02</code>。</p><p>scale 不能脱离原始分数量纲比较。判断谁主导行为，应查看 evaluation 或 cost cloud 的实际分项。</p><p><img src="'+s+`" alt="Critic 准备、淘汰、加权与短路"></p><h2 id="六、输出、失败与观测" tabindex="-1">六、输出、失败与观测 <a class="header-anchor" href="#六、输出、失败与观测" aria-label="Permalink to &quot;六、输出、失败与观测&quot;">​</a></h2><h3 id="_6-1-成功输出链" tabindex="-1">6.1 成功输出链 <a class="header-anchor" href="#_6-1-成功输出链" aria-label="Permalink to &quot;6.1 成功输出链&quot;">​</a></h3><p>最优轨迹的初始速度被转换成 <code>TwistStamped</code> 返回 Controller Server。当前系统中的主链为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FollowPath</span></span>
<span class="line"><span>  → controller_server</span></span>
<span class="line"><span>  → DWBLocalPlanner::computeVelocityCommands()</span></span>
<span class="line"><span>  → cmd_vel_nav</span></span>
<span class="line"><span>  → velocity_smoother</span></span>
<span class="line"><span>  → cmd_vel</span></span>
<span class="line"><span>  → 底盘适配节点</span></span></code></pre></div><p>DWB 限制的是建议速度；最终速度还受 <code>velocity_smoother</code> 的速度、加速度与死区约束。</p><h3 id="_6-2-失败与调试输出" tabindex="-1">6.2 失败与调试输出 <a class="header-anchor" href="#_6-2-失败与调试输出" aria-label="Permalink to &quot;6.2 失败与调试输出&quot;">​</a></h3><p>如果全部候选非法，DWB 抛出无合法轨迹异常。Controller Server 可在 <code>failure_tolerance</code> 内容忍短暂失败，持续失败才终止 FollowPath。</p><p>常用观测包括 evaluation、Marker、接收路径、变换后路径、局部轨迹和 cost cloud。Rotation Shim 内部也加载 DWB 时，要检查 Topic 是否重叠。</p><p><img src="`+d+`" alt="DWB 结果、异常与可观测输出"></p><h2 id="七、源码边界与排障重点" tabindex="-1">七、源码边界与排障重点 <a class="header-anchor" href="#七、源码边界与排障重点" aria-label="Permalink to &quot;七、源码边界与排障重点&quot;">​</a></h2><h3 id="_7-1-容易误判的边界" tabindex="-1">7.1 容易误判的边界 <a class="header-anchor" href="#_7-1-容易误判的边界" aria-label="Permalink to &quot;7.1 容易误判的边界&quot;">​</a></h3><ul><li><code>computeVelocityCommands()</code> 收到的 GoalChecker 不直接参与 DWB 评分；<code>RotateToGoal</code> 的容差是独立参数。</li><li>Path 裁剪与部分 TF 处理发生在 DWB 持有 Costmap 互斥锁之前。</li><li>个别 Pose 变换返回值未被逐项检查，TF 边缘故障可能表现为后续评分异常。</li><li>Critic 的 <code>prepare()</code> 返回失败时主要记录警告，不一定中止本轮。</li><li>动态速度限制变化时，要同时核对线速度上限及其平方缓存是否一致。</li><li>默认调试配置可能仍构造完整 evaluation，关闭发布并不等于没有计算开销。</li><li>DWB 命名空间下的 <code>stateful</code> 不是 DWB 自身读取的核心参数，不要与 GoalChecker 的同名参数混淆。</li></ul><h3 id="_7-2-按数据链定位问题" tabindex="-1">7.2 按数据链定位问题 <a class="header-anchor" href="#_7-2-按数据链定位问题" aria-label="Permalink to &quot;7.2 按数据链定位问题&quot;">​</a></h3><ul><li>没有候选：查当前速度、采样数、速度上下限与加速度窗口。</li><li>全部非法：查 footprint、局部 Costmap、TF、Obstacle Critic 和膨胀层。</li><li>轨迹贴不住路径：查变换后路径、MapGrid 距离场和 Align／Dist 权重。</li><li>终点抖动：查 RotateToGoal、GoalChecker 容差及 Oscillation 状态。</li><li>DWB 输出正常但底盘速度异常：继续查 <code>velocity_smoother</code> 与底盘适配节点。</li></ul><h2 id="八、完整数据流总结" tabindex="-1">八、完整数据流总结 <a class="header-anchor" href="#八、完整数据流总结" aria-label="Permalink to &quot;八、完整数据流总结&quot;">​</a></h2><h3 id="_8-1-一条主线看懂-dwb" tabindex="-1">8.1 一条主线看懂 DWB <a class="header-anchor" href="#_8-1-一条主线看懂-dwb" aria-label="Permalink to &quot;8.1 一条主线看懂 DWB&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Path + Pose + Odom + Local Costmap + SpeedLimit</span></span>
<span class="line"><span>  → Path 裁剪与 TF 变换</span></span>
<span class="line"><span>  → 速度窗口采样</span></span>
<span class="line"><span>  → 加速度约束轨迹推演</span></span>
<span class="line"><span>  → Critic prepare</span></span>
<span class="line"><span>  → 非法轨迹淘汰</span></span>
<span class="line"><span>  → 分项加权与短路</span></span>
<span class="line"><span>  → 最低总分轨迹</span></span>
<span class="line"><span>  → TwistStamped</span></span>
<span class="line"><span>  → Controller Server</span></span>
<span class="line"><span>  → Velocity Smoother</span></span>
<span class="line"><span>  → 底盘</span></span></code></pre></div><p>DWB 的本质不是“直接跟踪路径”，而是在当前局部地图、运动学约束和路径目标之间，持续做有限时域的离散优化。理解候选速度、未来轨迹和 Critic 分数这三层数据，就能把大多数“走不动、贴障碍、终点抖动、速度不对”的问题定位到具体环节。</p><h2 id="九、参考资料" tabindex="-1">九、参考资料 <a class="header-anchor" href="#九、参考资料" aria-label="Permalink to &quot;九、参考资料&quot;">​</a></h2><h3 id="_9-1-nav2-官方配置说明" tabindex="-1">9.1 Nav2 官方配置说明 <a class="header-anchor" href="#_9-1-nav2-官方配置说明" aria-label="Permalink to &quot;9.1 Nav2 官方配置说明&quot;">​</a></h3><p><a href="https://docs.nav2.org/configuration/packages/configuring-dwb-controller.html" target="_blank" rel="noreferrer">Nav2 DWB Controller 配置、插件与示例</a></p><h3 id="_9-2-上游源码入口" tabindex="-1">9.2 上游源码入口 <a class="header-anchor" href="#_9-2-上游源码入口" aria-label="Permalink to &quot;9.2 上游源码入口&quot;">​</a></h3><p><a href="https://github.com/ros-navigation/navigation2/blob/main/nav2_dwb_controller/README.md" target="_blank" rel="noreferrer">Nav2 DWB Controller 上游 README</a></p>`,69)])])}const P=e(p,[["render",h]]);export{f as __pageData,P as default};
